import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/simad.css';

/*
 * SimAd — a clickbait-style ad banner used by the PHISHBOOK training
 * simulation. It is intentionally designed to look like an enticing
 * promotional ad (the kind used in real phishing lures) but it never
 * collects any data and never leaves the app. Clicking it always routes
 * to /sim/ad-landing, a page that immediately reveals the simulation
 * and walks through the red flags the participant just saw.
 */
export default function SimAd({ variant = 'default' }) {
  const navigate = useNavigate();

  const copy = {
    default: {
      badge: 'Sponsored · Offer',
      kicker: 'Student Exclusive',
      headline: 'Unlock 12 months free of Lumen AI Assistant',
      sub: 'Activate within the next 10 minutes to lock in your free year.',
      cta: 'Unlock My Year',
    },
    sidebar: {
      badge: 'Sponsored · Offer',
      kicker: 'Student Exclusive',
      headline: 'Unlock 12 months free of Lumen AI Assistant',
      sub: 'Activate within the next 10 minutes to lock in your free year.',
      cta: 'Unlock My Year',
    },
  }[variant];

  return (
    <button
      type="button"
      className={`sim-ad sim-ad-${variant}`}
      onClick={() => navigate('/sim/ad-landing')}
    >
      <span className="sim-ad-sparkle" aria-hidden="true">✦</span>
      <span className="sim-ad-top-row">
        <span className="sim-ad-badge">{copy.badge}</span>
        {copy.kicker && <span className="sim-ad-kicker">{copy.kicker}</span>}
      </span>
      <span className="sim-ad-headline">{copy.headline}</span>
      <span className="sim-ad-sub">{copy.sub}</span>
      <span className="sim-ad-cta">{copy.cta} →</span>
    </button>
  );
}
